    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for top in range(h):
        common = list(grid[top])
        for bottom in range(top, h):
            if bottom > top:
                common = [common[c] if grid[bottom][c] == common[c] else -1 for c in range(w)]
            height = bottom - top + 1
            c = 0
            while c < w:
                if common[c] < 0:
                    c += 1
                    continue
                color = common[c]
                end = c + 1
                while end < w and common[end] == color:
                    end += 1
                width = end - c
                if height >= 4 and width >= 4 and height * width >= 20:
                    extend = ((top > 0 and all(grid[top-1][x] == color for x in range(c,end))) or
                              (bottom+1 < h and all(grid[bottom+1][x] == color for x in range(c,end))) or
                              (c > 0 and all(grid[y][c-1] == color for y in range(top,bottom+1))) or
                              (end < w and all(grid[y][end] == color for y in range(top,bottom+1))))
                    if not extend:
                        for y in range(top,bottom+1):
                            for x in range(c,end):
                                out[y][x] = 4
                c = end
    return out
